function validate(input) {
  const [{ Users = [], Transactions = [] }] = input;
  const users = new Set(), transfers = new Set();
  for (const [id, , credit] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (users.has(id)) return `user_id ${id} appears twice in Users.`;
    if (credit === null) return `User ${id} needs a credit.`;
    users.add(id);
  }
  for (const [id, from, to, amount, date] of Transactions) {
    if (id === null) return 'Every transaction needs a trans_id.';
    if (transfers.has(id)) return `trans_id ${id} appears twice in Transactions.`;
    transfers.add(id);
    if (!users.has(from)) return `Transaction ${id} is paid by user ${from}, who is not in Users.`;
    if (!users.has(to)) return `Transaction ${id} is paid to user ${to}, who is not in Users.`;
    if (amount === null || amount <= 0) return `Transaction ${id} needs a positive amount.`;
    if (date === null) return `Transaction ${id} needs a date.`;
  }
  return null;
}

