function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const names = ['Moustafa', 'Jonathan', 'Winston', 'Luis', 'Ana', 'Ravi', 'Sofia', 'Ana'];
  // Credits and amounts share round values so balances often land exactly on 0 or just below it.
  const credits = small ? [0, 10, 100, 200, 500, 800] : [0, 100, 250, 500, 1000, 5000];
  const amounts = small ? [10, 90, 100, 110, 200, 400, 500] : [10, 50, 100, 200, 400, 500, 1000];
  const dates = ['2020-08-01', '2020-08-02', '2020-08-03', '2020-09-15', '2021-01-01'];
  const userCount = small ? Math.floor(rand() * 7) : 500;
  const transferCount = userCount < 2 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const Users = [], Transactions = [];
  for (let id = 1; id <= userCount; id++) Users.push([id, pick(names), pick(credits)]);
  for (let id = 1; id <= transferCount; id++) {
    const from = 1 + Math.floor(rand() * userCount);
    let to = 1 + Math.floor(rand() * (userCount - 1));
    if (to >= from) to++;
    Transactions.push([id, from, to, pick(amounts), pick(dates)]);
  }
  return [{ Users, Transactions }];
}
